package com.training.accounting.customer; import com.training.accounting.user.AppUser; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { private final CustomerRepository r; public DashboardController(CustomerRepository r){this.r=r;} @GetMapping public Map<String,Object> get(Authentication a){Long b=((AppUser)a.getDetails()).getBusinessId();return Map.of("totalCustomers",r.countByBusinessId(b),"status","RUNNING");} }
